//! 🧊️ Full typed BRep topology, analytic geometry, p-curves and NURBS parameter sequences.
use semio_framework_value::{ValueError,ValueRefusalKind};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use crate::brep::schema::snapshot::{SemioBrepSnapshot,BrepVertex,BrepEdge,BrepLoop,BrepLoopEdge,BrepCoedge,BrepFace,BrepShell,BrepShellFace,BrepSolid,BrepSolidShell,BrepCurve,BrepCurve2,BrepSurface};
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint2,SemioPoint3};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,Reconstruction},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding}};
use std::collections::BTreeMap;
use semio_framework_os_kernel::sqlite_snapshot::transfer;
fn number(n:usize)->Result<i64,ValueError>{i64::try_from(n).map_err(|e|ValueError::new(ValueRefusalKind::WorkLimit,e.to_string()))}
fn boolean(n:i64)->Result<bool,ValueError>{match n{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep boolean"))}}
fn identity<'a>(r:impl std::borrow::Borrow<SqliteRow<'a>>,n:usize)->Result<(),ValueError>{let r=*r.borrow();if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep row identity or columns"))}else{Ok(())}}
fn point3(r:SqliteRow<'_>,i:usize)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:r.real(i)?,y:r.real(i+1)?,z:r.real(i+2)?})}
fn point2(r:SqliteRow<'_>,i:usize)->Result<SemioPoint2,ValueError>{Ok(SemioPoint2{x:r.real(i)?,y:r.real(i+1)?})}
fn put3(c:&mut[Cell<'_>],i:usize,p:SemioPoint3){c[i]=Cell::Real(p.x);c[i+1]=Cell::Real(p.y);c[i+2]=Cell::Real(p.z);}
fn put2(c:&mut[Cell<'_>],i:usize,p:SemioPoint2){c[i]=Cell::Real(p.x);c[i+1]=Cell::Real(p.y);}
fn scalars(table:&str,id:i64,values:&[f64],p:&mut Projection<'_,'_>)->Result<(),ValueError>{for(ordinal,v)in values.iter().enumerate(){p.insert_float(table,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(*v)])?;}Ok(())}
fn points3(table:&str,id:i64,values:&[SemioPoint3],p:&mut Projection<'_,'_>)->Result<(),ValueError>{for(ordinal,v)in values.iter().enumerate(){p.insert_float(table,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(v.x),Cell::Real(v.y),Cell::Real(v.z)])?;}Ok(())}
fn project_curve3(curve:&BrepCurve,p:&mut Projection<'_,'_>)->Result<i64,ValueError>{let mut c=[Cell::Null;17];match curve{BrepCurve::Line{origin,direction}=>{c[0]=Cell::Text("line");put3(&mut c,1,*origin);put3(&mut c,4,*direction);},BrepCurve::Circle{center,axis,radius}=>{c[0]=Cell::Text("circle");put3(&mut c,7,*center);put3(&mut c,10,*axis);c[13]=Cell::Real(*radius);},BrepCurve::Ellipse{center,axis,radius_major,radius_minor}=>{c[0]=Cell::Text("ellipse");put3(&mut c,7,*center);put3(&mut c,10,*axis);c[14]=Cell::Real(*radius_major);c[15]=Cell::Real(*radius_minor);},BrepCurve::Nurbs{degree,..}=>{c[0]=Cell::Text("nurbs");c[16]=Cell::Integer(i64::from(*degree));}}let id=p.insert_float("semio_brep_curve3",&c)?;if let BrepCurve::Nurbs{control_points,weights,knots,..}=curve{points3("semio_brep_curve3_point",id,control_points,p)?;scalars("semio_brep_curve3_weight",id,weights,p)?;scalars("semio_brep_curve3_knot",id,knots,p)?;}Ok(id)}
fn project_curve2(curve:&BrepCurve2,p:&mut Projection<'_,'_>)->Result<i64,ValueError>{let mut c=[Cell::Null;13];match curve{BrepCurve2::Line{origin,direction}=>{c[0]=Cell::Text("line");put2(&mut c,1,*origin);put2(&mut c,3,*direction);},BrepCurve2::Circle{center,radius}=>{c[0]=Cell::Text("circle");put2(&mut c,5,*center);c[9]=Cell::Real(*radius);},BrepCurve2::Ellipse{center,x_axis,radius_major,radius_minor}=>{c[0]=Cell::Text("ellipse");put2(&mut c,5,*center);put2(&mut c,7,*x_axis);c[10]=Cell::Real(*radius_major);c[11]=Cell::Real(*radius_minor);},BrepCurve2::Nurbs{degree,..}=>{c[0]=Cell::Text("nurbs");c[12]=Cell::Integer(i64::from(*degree));}}let id=p.insert_float("semio_brep_curve2",&c)?;if let BrepCurve2::Nurbs{control_points,weights,knots,..}=curve{for(ordinal,v)in control_points.iter().enumerate(){p.insert_float("semio_brep_curve2_point",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(v.x),Cell::Real(v.y)])?;}scalars("semio_brep_curve2_weight",id,weights,p)?;scalars("semio_brep_curve2_knot",id,knots,p)?;}Ok(id)}
fn project_surface(surface:&BrepSurface,p:&mut Projection<'_,'_>)->Result<i64,ValueError>{let mut c=[Cell::Null;21];match surface{BrepSurface::Plane{origin,normal}=>{c[0]=Cell::Text("plane");put3(&mut c,1,*origin);put3(&mut c,10,*normal);},BrepSurface::Cylinder{origin,axis,radius}=>{c[0]=Cell::Text("cylinder");put3(&mut c,1,*origin);put3(&mut c,4,*axis);c[13]=Cell::Real(*radius);},BrepSurface::Cone{origin,axis,radius,half_angle}=>{c[0]=Cell::Text("cone");put3(&mut c,1,*origin);put3(&mut c,4,*axis);c[13]=Cell::Real(*radius);c[14]=Cell::Real(*half_angle);},BrepSurface::Sphere{center,radius}=>{c[0]=Cell::Text("sphere");put3(&mut c,7,*center);c[13]=Cell::Real(*radius);},BrepSurface::Torus{center,axis,major_radius,minor_radius}=>{c[0]=Cell::Text("torus");put3(&mut c,7,*center);put3(&mut c,4,*axis);c[15]=Cell::Real(*major_radius);c[16]=Cell::Real(*minor_radius);},BrepSurface::Nurbs{u_count,v_count,degree_u,degree_v,..}=>{c[0]=Cell::Text("nurbs");c[17]=Cell::Integer(i64::from(*u_count));c[18]=Cell::Integer(i64::from(*v_count));c[19]=Cell::Integer(i64::from(*degree_u));c[20]=Cell::Integer(i64::from(*degree_v));}}let id=p.insert_float("semio_brep_surface",&c)?;if let BrepSurface::Nurbs{control_points,weights,knots_u,knots_v,..}=surface{points3("semio_brep_surface_point",id,control_points,p)?;scalars("semio_brep_surface_weight",id,weights,p)?;scalars("semio_brep_surface_knot_u",id,knots_u,p)?;scalars("semio_brep_surface_knot_v",id,knots_v,p)?;}Ok(id)}
fn details<'a>(db:&'a SqliteDatabase,name:&str,n:usize,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,ValueError>{let mut result=BTreeMap::new();for(count,row)in float_rows(db,name,c)?.into_iter().enumerate(){identity(row,n)?;if result.insert(row.rowid,row).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate BRep row identity"));}if count%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn groups<'a>(db:&'a SqliteDatabase,name:&str,n:usize,parents:&BTreeMap<i64,SqliteRow<'_>>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,ValueError>{let mut result=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();for row in details(db,name,n,c)?.into_values(){if !parents.contains_key(&row.integer(1)?){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"dangling BRep sequence owner"));}row.integer(2)?;result.entry(row.integer(1)?).or_default().push(row);}for rows in result.values_mut(){rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(ordinal,r)in rows.iter().enumerate(){if r.integer(2)?!=number(ordinal)?{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"BRep sequence ordinals must be contiguous"));}}}Ok(result)}
fn shape(row:SqliteRow<'_>,active:&[usize])->Result<(),ValueError>{for i in 2..row.values.len(){if !active.contains(&i)&&!row.is_null(i)?{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"contradictory BRep analytic geometry fields"));}}Ok(())}
fn real_sequence(rows:Vec<SqliteRow<'_>>)->Result<Vec<f64>,ValueError>{rows.into_iter().map(|r|r.real(3)).collect()}
fn curves3(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepCurve>,ValueError>{let rows=details(db,"semio_brep_curve3",18,c)?;let mut points=groups(db,"semio_brep_curve3_point",6,&rows,c)?;let mut weights=groups(db,"semio_brep_curve3_weight",4,&rows,c)?;let mut knots=groups(db,"semio_brep_curve3_knot",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let curve=match row.text(1)?{
"line"=>{shape(row,&[2,3,4,5,6,7])?;BrepCurve::Line{origin:point3(row,2)?,direction:point3(row,5)?}},"circle"=>{shape(row,&[8,9,10,11,12,13,14])?;BrepCurve::Circle{center:point3(row,8)?,axis:point3(row,11)?,radius:row.real(14)?}},"ellipse"=>{shape(row,&[8,9,10,11,12,13,15,16])?;BrepCurve::Ellipse{center:point3(row,8)?,axis:point3(row,11)?,radius_major:row.real(15)?,radius_minor:row.real(16)?}},"nurbs"=>{shape(row,&[17])?;BrepCurve::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point3(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,degree:u32::try_from(row.integer(17)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,knots:real_sequence(knots.remove(&id).unwrap_or_default())?}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown BRep 3D curve kind"))};result.insert(id,curve);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"parameter sequences on non-NURBS 3D curves"));}Ok(result)}
fn curves2(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepCurve2>,ValueError>{let rows=details(db,"semio_brep_curve2",14,c)?;let mut points=groups(db,"semio_brep_curve2_point",5,&rows,c)?;let mut weights=groups(db,"semio_brep_curve2_weight",4,&rows,c)?;let mut knots=groups(db,"semio_brep_curve2_knot",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let curve=match row.text(1)?{
"line"=>{shape(row,&[2,3,4,5])?;BrepCurve2::Line{origin:point2(row,2)?,direction:point2(row,4)?}},"circle"=>{shape(row,&[6,7,10])?;BrepCurve2::Circle{center:point2(row,6)?,radius:row.real(10)?}},"ellipse"=>{shape(row,&[6,7,8,9,11,12])?;BrepCurve2::Ellipse{center:point2(row,6)?,x_axis:point2(row,8)?,radius_major:row.real(11)?,radius_minor:row.real(12)?}},"nurbs"=>{shape(row,&[13])?;BrepCurve2::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point2(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,degree:u32::try_from(row.integer(13)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,knots:real_sequence(knots.remove(&id).unwrap_or_default())?}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown BRep p-curve kind"))};result.insert(id,curve);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"parameter sequences on non-NURBS p-curves"));}Ok(result)}
fn surfaces(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,BrepSurface>,ValueError>{let rows=details(db,"semio_brep_surface",22,c)?;let mut points=groups(db,"semio_brep_surface_point",6,&rows,c)?;let mut weights=groups(db,"semio_brep_surface_weight",4,&rows,c)?;let mut knots_u=groups(db,"semio_brep_surface_knot_u",4,&rows,c)?;let mut knots_v=groups(db,"semio_brep_surface_knot_v",4,&rows,c)?;let mut result=BTreeMap::new();for row in rows.into_values(){let id=row.rowid;let surface=match row.text(1)?{
"plane"=>{shape(row,&[2,3,4,11,12,13])?;BrepSurface::Plane{origin:point3(row,2)?,normal:point3(row,11)?}},"cylinder"=>{shape(row,&[2,3,4,5,6,7,14])?;BrepSurface::Cylinder{origin:point3(row,2)?,axis:point3(row,5)?,radius:row.real(14)?}},"cone"=>{shape(row,&[2,3,4,5,6,7,14,15])?;BrepSurface::Cone{origin:point3(row,2)?,axis:point3(row,5)?,radius:row.real(14)?,half_angle:row.real(15)?}},"sphere"=>{shape(row,&[8,9,10,14])?;BrepSurface::Sphere{center:point3(row,8)?,radius:row.real(14)?}},"torus"=>{shape(row,&[5,6,7,8,9,10,16,17])?;BrepSurface::Torus{center:point3(row,8)?,axis:point3(row,5)?,major_radius:row.real(16)?,minor_radius:row.real(17)?}},"nurbs"=>{shape(row,&[18,19,20,21])?;BrepSurface::Nurbs{control_points:points.remove(&id).unwrap_or_default().into_iter().map(|r|point3(r,3)).collect::<Result<_,_>>()?,weights:real_sequence(weights.remove(&id).unwrap_or_default())?,u_count:u32::try_from(row.integer(18)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,v_count:u32::try_from(row.integer(19)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,degree_u:u32::try_from(row.integer(20)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,degree_v:u32::try_from(row.integer(21)?).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?,knots_u:real_sequence(knots_u.remove(&id).unwrap_or_default())?,knots_v:real_sequence(knots_v.remove(&id).unwrap_or_default())?}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown BRep surface kind"))};result.insert(id,surface);c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,result.len(),0)?;}if !points.is_empty()||!weights.is_empty()||!knots_u.is_empty()||!knots_v.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"parameter sequences on non-NURBS surfaces"));}Ok(result)}
fn native_rows(rows:&[SqliteRow<'_>],columns:usize,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut ids=transfer::reserve(rows.len(),c)?;for(at,row)in rows.iter().enumerate(){identity(row,columns)?;if row.integer(1)?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep document parent"));}row.text(3)?;ids.push(row.rowid);if(at+1)%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,at+1,rows.len())?;}}transfer::heap_sort(&mut ids,SqliteSnapshotPhase::ReconstructSnapshot,c,|a,b,_|Ok(a.cmp(b)))?;for(at,id)in ids.iter().enumerate(){if at>0&&ids[at-1]==*id{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate BRep row identity"));}if(at+1)%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,at+1,rows.len())?;}}Ok(())}
impl ArtifactSqliteSnapshot for SemioBrepSnapshot{
fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{crate::standards::v1::subsets::brep::io::sqlite::snapshot::native_encoding::encode(self,encoding,control)}
fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{crate::standards::v1::subsets::brep::io::sqlite::snapshot::native_decoding::decode(payload,control)}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let result=(||->Result<(),ValueError>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()})();result}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{let result=(||->Result<semio_framework_os_kernel::io_schema::IoOutcome<()>,ValueError>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="brep"){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio owned snapshot dialect differs from its dedicated semantic subset"));}
let row=database.table("semio_brep_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio owned document identity differs from projected semantic fields"));}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))})();result.map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{self.project_sqlite_database(c)}
fn from_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError> {let result=(||->Result<Self,ValueError>{ Self::reconstruct_sqlite_database(db, c, Self::SQLITE_SCHEMA) })();result}
}

impl SemioBrepSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(db:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,ValueError> {
c.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(db,declared_schema,c.limits())?;let doc=single_float_row(db,"semio_brep_document")?;identity(doc,3)?;if doc.rowid!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep document identity"));}let next_label=doc.text(2)?.parse::<u64>().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;if next_label.to_string()!=doc.text(2)?{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"noncanonical BRep unsigned label"));}
let vertex_rows=ordered_float_rows(db,"semio_brep_vertex",2,c)?;let edge_rows=ordered_float_rows(db,"semio_brep_edge",2,c)?;let loop_rows=ordered_float_rows(db,"semio_brep_loop",2,c)?;let face_rows=ordered_float_rows(db,"semio_brep_face",2,c)?;let shell_rows=ordered_float_rows(db,"semio_brep_shell",2,c)?;let solid_rows=ordered_float_rows(db,"semio_brep_solid",2,c)?;let coedge_rows=ordered_float_rows(db,"semio_brep_coedge",2,c)?;
native_rows(&vertex_rows,8,c)?;native_rows(&edge_rows,8,c)?;native_rows(&loop_rows,4,c)?;native_rows(&face_rows,8,c)?;native_rows(&shell_rows,4,c)?;native_rows(&solid_rows,4,c)?;native_rows(&coedge_rows,12,c)?;
let raw_loops=details(db,"semio_brep_loop",4,c)?;let raw_faces=details(db,"semio_brep_face",8,c)?;let raw_shells=details(db,"semio_brep_shell",4,c)?;let raw_solids=details(db,"semio_brep_solid",4,c)?;let mut loop_edges=groups(db,"semio_brep_loop_edge",5,&raw_loops,c)?;let mut inner_loops=groups(db,"semio_brep_inner_loop",4,&raw_faces,c)?;let mut shell_faces=groups(db,"semio_brep_shell_face",5,&raw_shells,c)?;let mut solid_shells=groups(db,"semio_brep_solid_shell",5,&raw_solids,c)?;let mut curves3=curves3(db,c)?;let mut curves2=curves2(db,c)?;let mut surfaces=surfaces(db,c)?;let mut r=Reconstruction::new(c)?;
let mut vertices=Vec::new();for row in vertex_rows{vertices.push(BrepVertex{id:r.text(row.text(3)?)?,point:point3(row,4)?,tol:row.real(7)?});r.checkpoint()?;}
let mut edges=Vec::new();for row in edge_rows{edges.push(BrepEdge{id:r.text(row.text(3)?)?,start_vertex:r.text(row.text(4)?)?,end_vertex:r.text(row.text(5)?)?,curve:curves3.remove(&row.integer(6)?).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"missing multiply owned or dangling edge curve"))?,tol:row.real(7)?});r.checkpoint()?;}
let mut loops=Vec::new();for row in loop_rows{let mut native=Vec::new();for edge in loop_edges.remove(&row.rowid).unwrap_or_default(){native.push(BrepLoopEdge{edge:r.text(edge.text(3)?)?,orientation:boolean(edge.integer(4)?)?});}loops.push(BrepLoop{id:r.text(row.text(3)?)?,edges:native});r.checkpoint()?;}
let mut faces=Vec::new();for row in face_rows{let mut native=Vec::new();for l in inner_loops.remove(&row.rowid).unwrap_or_default(){native.push(r.text(l.text(3)?)?);}faces.push(BrepFace{id:r.text(row.text(3)?)?,outer_loop:r.text(row.text(4)?)?,inner_loops:native,surface:surfaces.remove(&row.integer(5)?).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"missing multiply owned or dangling face surface"))?,orientation:boolean(row.integer(6)?)?,tol:row.real(7)?});r.checkpoint()?;}
let mut shells=Vec::new();for row in shell_rows{let mut native=Vec::new();for f in shell_faces.remove(&row.rowid).unwrap_or_default(){native.push(BrepShellFace{face:r.text(f.text(3)?)?,orientation:boolean(f.integer(4)?)?});}shells.push(BrepShell{id:r.text(row.text(3)?)?,faces:native});r.checkpoint()?;}
let mut solids=Vec::new();for row in solid_rows{let mut native=Vec::new();for s in solid_shells.remove(&row.rowid).unwrap_or_default(){native.push(BrepSolidShell{shell:r.text(s.text(3)?)?,is_void:boolean(s.integer(4)?)?});}solids.push(BrepSolid{id:r.text(row.text(3)?)?,shells:native});r.checkpoint()?;}
let mut coedges=Vec::new();for row in coedge_rows{let pcurve=if row.is_null(6)?{None}else{Some(curves2.remove(&row.integer(6)?).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"missing multiply owned or dangling p-curve"))?)};coedges.push(BrepCoedge{id:r.text(row.text(3)?)?,edge:r.text(row.text(4)?)?,forward:boolean(row.integer(5)?)?,pcurve,prange:(row.real(7)?,row.real(8)?),loop_id:r.text(row.text(9)?)?,next:r.text(row.text(10)?)?,prev:r.text(row.text(11)?)?});r.checkpoint()?;}
if !curves3.is_empty()||!curves2.is_empty()||!surfaces.is_empty()||!loop_edges.is_empty()||!inner_loops.is_empty()||!shell_faces.is_empty()||!solid_shells.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"orphan BRep owned geometry or relationship"));}let value=Self{schema:r.text(doc.text(1)?)?,vertices,edges,loops,faces,shells,solids,coedges,next_label};r.checkpoint()?;Ok(value)
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_brep_vertex"=>&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7)],"semio_brep_edge"=>&[FloatColumn::Binary64(7)],"semio_brep_coedge"=>&[FloatColumn::Binary64(7),FloatColumn::Binary64(8)],"semio_brep_face"=>&[FloatColumn::Binary64(7)],"semio_brep_curve3"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15),FloatColumn::Binary64(16)],"semio_brep_curve3_point"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_brep_curve3_weight"=>&[FloatColumn::Binary64(3)],"semio_brep_curve3_knot"=>&[FloatColumn::Binary64(3)],"semio_brep_curve2"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12)],"semio_brep_curve2_point"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_brep_curve2_weight"=>&[FloatColumn::Binary64(3)],"semio_brep_curve2_knot"=>&[FloatColumn::Binary64(3)],"semio_brep_surface"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15),FloatColumn::Binary64(16),FloatColumn::Binary64(17)],"semio_brep_surface_point"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_brep_surface_weight"=>&[FloatColumn::Binary64(3)],"semio_brep_surface_knot_u"=>&[FloatColumn::Binary64(3)],"semio_brep_surface_knot_v"=>&[FloatColumn::Binary64(3)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,ValueError>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),ValueError>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,ValueError>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),ValueError>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,ValueError>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=transfer::reserve(table_rows.rows.len(),control)?;for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,ValueError>{let mut result=transfer::reserve(db.table(table)?.rows.len(),control)?;for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,ValueError>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioBrepSnapshot {
/// 📏️ Bounds the full native topological identities and analytic/NURBS components.
pub fn native_fields(&self,b:&mut Bound<'_, '_>)->Result<(),ValueError>{b.text(&self.schema)?;b.scalars(1)?;
b.entities(self.vertices.len())?;for vertex in &self.vertices{b.text(&vertex.id)?;b.scalars(4)?;}
b.entities(self.edges.len())?;for edge in &self.edges{b.text(&edge.id)?;b.text(&edge.start_vertex)?;b.text(&edge.end_vertex)?;b.scalars(1)?;match &edge.curve{BrepCurve::Line{..}=>b.scalars(6)?,BrepCurve::Circle{..}=>b.scalars(7)?,BrepCurve::Ellipse{..}=>b.scalars(8)?,BrepCurve::Nurbs{control_points,weights,knots,..}=>{native_nurbs(control_points.len(),3,weights.len(),knots.len(),b)?;b.scalars(1)?;}}}
b.entities(self.loops.len())?;for item in &self.loops{b.text(&item.id)?;b.entities(item.edges.len())?;for edge in &item.edges{b.text(&edge.edge)?;b.scalars(1)?;}}
b.entities(self.coedges.len())?;for edge in &self.coedges{b.text(&edge.id)?;b.text(&edge.edge)?;b.text(&edge.loop_id)?;b.text(&edge.next)?;b.text(&edge.prev)?;b.scalars(3)?;if let Some(curve)=&edge.pcurve{match curve{BrepCurve2::Line{..}=>b.scalars(4)?,BrepCurve2::Circle{..}=>b.scalars(3)?,BrepCurve2::Ellipse{..}=>b.scalars(6)?,BrepCurve2::Nurbs{control_points,weights,knots,..}=>{native_nurbs(control_points.len(),2,weights.len(),knots.len(),b)?;b.scalars(1)?;}}}}
b.entities(self.faces.len())?;for face in &self.faces{b.text(&face.id)?;b.text(&face.outer_loop)?;b.entities(face.inner_loops.len())?;for item in &face.inner_loops{b.text(item)?;}b.scalars(2)?;match &face.surface{BrepSurface::Plane{..}=>b.scalars(6)?,BrepSurface::Cylinder{..}=>b.scalars(7)?,BrepSurface::Cone{..}=>b.scalars(8)?,BrepSurface::Sphere{..}=>b.scalars(4)?,BrepSurface::Torus{..}=>b.scalars(8)?,BrepSurface::Nurbs{control_points,weights,knots_u,knots_v,..}=>{native_nurbs(control_points.len(),3,weights.len(),knots_u.len(),b)?;b.entities(knots_v.len())?;b.scalars(knots_v.len())?;b.scalars(4)?;}}}
b.entities(self.shells.len())?;for shell in &self.shells{b.text(&shell.id)?;b.entities(shell.faces.len())?;for face in &shell.faces{b.text(&face.face)?;b.scalars(1)?;}}
b.entities(self.solids.len())?;for solid in &self.solids{b.text(&solid.id)?;b.entities(solid.shells.len())?;for shell in &solid.shells{b.text(&shell.shell)?;b.scalars(1)?;}}Ok(())}
}
fn native_nurbs(points:usize,width:usize,weights:usize,knots:usize,b:&mut Bound<'_, '_>)->Result<(),ValueError>{b.entities(points)?;b.scalars(points.checked_mul(width).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"BRep native point scalar overflow"))?)?;b.entities(weights)?;b.scalars(weights)?;b.entities(knots)?;b.scalars(knots)}

impl SemioBrepSnapshot {
    /// 🪶️ Projects the owned subset into its declared relational writer while preserving refusals.
    pub fn project_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.insert_key_float("semio_brep_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.next_label.to_string())])?;
for(ordinal,v)in self.vertices.iter().enumerate(){p.insert_key_float("semio_brep_vertex",number(ordinal+1)?,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&v.id),Cell::Real(v.point.x),Cell::Real(v.point.y),Cell::Real(v.point.z),Cell::Real(v.tol)])?;}
for(ordinal,e)in self.edges.iter().enumerate(){let curve=project_curve3(&e.curve,&mut p)?;p.insert_key_float("semio_brep_edge",number(ordinal+1)?,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&e.id),Cell::Text(&e.start_vertex),Cell::Text(&e.end_vertex),Cell::Integer(curve),Cell::Real(e.tol)])?;}
for(ordinal,l)in self.loops.iter().enumerate(){let id=number(ordinal+1)?;p.insert_key_float("semio_brep_loop",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&l.id)])?;for(ordinal,e)in l.edges.iter().enumerate(){p.insert_float("semio_brep_loop_edge",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&e.edge),Cell::Integer(i64::from(e.orientation))])?;}}
for(ordinal,f)in self.faces.iter().enumerate(){let id=number(ordinal+1)?;let surface=project_surface(&f.surface,&mut p)?;p.insert_key_float("semio_brep_face",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&f.id),Cell::Text(&f.outer_loop),Cell::Integer(surface),Cell::Integer(i64::from(f.orientation)),Cell::Real(f.tol)])?;for(ordinal,l)in f.inner_loops.iter().enumerate(){p.insert_float("semio_brep_inner_loop",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(l)])?;}}
for(ordinal,s)in self.shells.iter().enumerate(){let id=number(ordinal+1)?;p.insert_key_float("semio_brep_shell",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.id)])?;for(ordinal,f)in s.faces.iter().enumerate(){p.insert_float("semio_brep_shell_face",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&f.face),Cell::Integer(i64::from(f.orientation))])?;}}
for(ordinal,s)in self.solids.iter().enumerate(){let id=number(ordinal+1)?;p.insert_key_float("semio_brep_solid",id,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.id)])?;for(ordinal,l)in s.shells.iter().enumerate(){p.insert_float("semio_brep_solid_shell",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(&l.shell),Cell::Integer(i64::from(l.is_void))])?;}}
for(ordinal,e)in self.coedges.iter().enumerate(){let curve=e.pcurve.as_ref().map(|v|project_curve2(v,&mut p)).transpose()?;p.insert_key_float("semio_brep_coedge",number(ordinal+1)?,&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&e.id),Cell::Text(&e.edge),Cell::Integer(i64::from(e.forward)),curve.map(Cell::Integer).unwrap_or(Cell::Null),Cell::Real(e.prange.0),Cell::Real(e.prange.1),Cell::Text(&e.loop_id),Cell::Text(&e.next),Cell::Text(&e.prev)])?;}p.finish()}
}

